<!doctype html><html lang="pt"><head><meta charset="utf-8"><title>{{$ticket->ticket_number}}</title><style>body{font-family:monospace;width:76mm;margin:0 auto;padding:4mm;font-size:14px}h1{font-size:22px;margin:5px 0}.line{border-top:1px dashed #000;margin:8px 0}.item{margin:10px 0;font-size:17px;font-weight:bold}.note{font-size:13px;font-weight:normal}button{width:100%;padding:10px}@media print{button{display:none}}</style></head><body>@if($copy)<div style="text-align:center;font-weight:bold">*** CÓPIA / REIMPRESSÃO ***</div>@endif<h1>{{$ticket->order->table?->name??ucfirst($ticket->order->channel)}}</h1><div>{{$ticket->order->order_number}} · {{$ticket->station->name}}</div><div>{{$ticket->queued_at->format('d/m/Y H:i')}}</div><div class="line"></div>@foreach($ticket->items as $i)<div class="item">{{rtrim(rtrim(number_format((float)$i->orderItem->quantity,2,',','.'),'0'),',')}}x {{$i->orderItem->product_name}}@if($i->orderItem->notes)<div class="note">Obs: {{$i->orderItem->notes}}</div>@endif</div>@endforeach<div class="line"></div><button onclick="window.print()">Imprimir ticket</button></body></html>
